import { LibraryError } from './libraryErrors';
import path from 'path';
import type { ProjectLibrary } from './ProjectLibrary';
import { closeListener, type listenLocally } from '../library/http';

interface PreviewReference {
  projectId: string;
  sessionId: string;
  variantId: string;
}
type PreviewServer = Awaited<ReturnType<typeof listenLocally>>;

export class StaticLibraryPreviews {
  private readonly previews = new Map<string, Promise<PreviewServer>>();
  constructor(
    private readonly library: ProjectLibrary,
    private readonly startPreview: (root: string) => Promise<PreviewServer>,
  ) {}

  async url(reference: PreviewReference): Promise<string> {
    const found = await this.library.variant(reference);
    if (!found || !found.detail.hasStaticPreview)
      throw new LibraryError(
        'preview_unavailable',
        'This direction requires an interactive workspace preview',
      );
    const { manifest, variantDir } = found.detail;
    let root: string;
    let entryPath: string;
    if (manifest.tree && manifest.serve?.kind === 'static') {
      root = await found.history.store.extractToCache({
        projectPath: found.projectPath,
        treeSha: manifest.tree.treeSha,
        commitish: manifest.tree.commitSha,
      });
      entryPath = manifest.serve.entryPath;
    } else if (manifest.preview.kind === 'static') {
      root = path.join(variantDir, manifest.preview.rootPath);
      entryPath = manifest.preview.entryPath;
    } else {
      throw new LibraryError(
        'preview_unavailable',
        'This direction has no saved static preview',
      );
    }
    const key = JSON.stringify([reference, root]);
    let pending = this.previews.get(key);
    if (!pending) {
      pending = this.startPreview(root);
      this.previews.set(key, pending);
      void pending.catch(() => this.previews.delete(key));
    }
    return `${(await pending).url}/${entryPath.split('/').map(encodeURIComponent).join('/')}`;
  }

  async close(): Promise<void> {
    const previews = await Promise.allSettled(this.previews.values());
    await Promise.all(
      previews.flatMap((preview) =>
        preview.status === 'fulfilled'
          ? [closeListener(preview.value.server)]
          : [],
      ),
    );
    this.previews.clear();
  }
}
